const fs = require("fs");
const path = require("path");

const OLD = "disableTooltip";
const NEW = "hideHint";
const TARGET_TAGS = new Set(["app-pill", "app-fancy-pill", "app-status-pill"]);

/** Walk a template, renaming the input only on target tags; return {text, refs}. */
function transformTemplate(text) {
    const refs = new Set();
    let out = "";
    let i = 0;
    while (i < text.length) {
        if (text.startsWith("<!--", i)) {
            const end = text.indexOf("-->", i);
            const stop = end === -1 ? text.length : end + 3;
            out += text.slice(i, stop);
            i = stop;
            continue;
        }
        if (text[i] === "<" && /[a-zA-Z]/.test(text[i + 1] || "")) {
            const m = /^<([a-zA-Z][a-zA-Z0-9-]*)/.exec(text.slice(i));
            const tag = m[1];
            // find end of the open tag, honouring quoted attribute values
            let j = i + m[0].length;
            let quote = null;
            while (j < text.length) {
                const c = text[j];
                if (quote) {
                    if (c === quote) quote = null;
                } else if (c === '"' || c === "'") {
                    quote = c;
                } else if (c === ">") {
                    break;
                }
                j++;
            }
            const attrSpan = text.slice(i + m[0].length, j);
            let newAttrs = attrSpan;
            if (TARGET_TAGS.has(tag)) {
                newAttrs = renameAttrs(attrSpan);
            }
            for (const r of attrSpan.matchAll(/(^|\s)#([a-zA-Z][a-zA-Z0-9_$]*)/g)) {
                if (TARGET_TAGS.has(tag)) refs.add(r[2]);
            }
            out += "<" + tag + newAttrs + text.slice(j, Math.min(j + 1, text.length));
            i = j + 1;
            continue;
        }
        out += text[i];
        i++;
    }
    return { text: out, refs };
}

/** Rename only attribute NAMES (never values) inside a tag's attribute span. */
function renameAttrs(span) {
    let out = "";
    let i = 0;
    const re = /([^\s=/>]+)(\s*=\s*("[^"]*"|'[^']*'|[^\s>]+))?/g;
    let m;
    while ((m = re.exec(span)) !== null) {
        out += span.slice(i, m.index);
        let name = m[1];
        const rest = m[2] || "";
        if (name === OLD) name = NEW;
        else if (name === "[" + OLD + "]") name = "[" + NEW + "]";
        out += name + rest;
        i = m.index + m[0].length;
    }
    out += span.slice(i);
    return out;
}

function applyRefs(text, refs) {
    for (const r of refs) {
        text = text.replace(
            new RegExp("\\b" + r + "\\.(" + OLD + ")\\b", "g"),
            r + "." + NEW
        );
    }
    return text;
}

/** Locate `template: ` + backtick-delimited literal in a .ts file. */
function templateRange(src) {
    const m = /template\s*:\s*`/.exec(src);
    if (!m) return null;
    const start = m.index + m[0].length;
    let j = start;
    while (j < src.length) {
        if (src[j] === "\\") { j += 2; continue; }
        if (src[j] === "`") break;
        j++;
    }
    return [ start, j ];
}

const LIB_PILL_FILES = new Set([
    "src/app/lib/pill.component.ts",
    "src/app/lib/fancy-pill.component.ts",
    "src/app/lib/status-pill.component.ts"
]);

function transformTs(src, rel) {
    const range = templateRange(src);
    let head = src, tmpl = "", tail = "";
    if (range) {
        head = src.slice(0, range[0]);
        tmpl = src.slice(range[0], range[1]);
        tail = src.slice(range[1]);
    }

    let refs = new Set();
    if (range) {
        const r = transformTemplate(tmpl);
        tmpl = r.text;
        refs = r.refs;
        // Inside the three pill components the template reads the own input.
        if (LIB_PILL_FILES.has(rel)) {
            tmpl = tmpl.replace(new RegExp("\\b" + OLD + "\\b", "g"), NEW);
        }
        tmpl = applyRefs(tmpl, refs);
    }

    const fixCode = (code) => {
        if (LIB_PILL_FILES.has(rel)) {
            // declaration + this.disableTooltip() reads
            return code.replace(new RegExp("\\b" + OLD + "\\b", "g"), NEW);
        }
        // reads through viewChild/viewChildren of the pill family
        code = code.replace(/this\.(fancy|firstPill)\(\)(\??\.)disableTooltip\b/g, `this.$1()$2${NEW}`);
        code = code.replace(/\b(fancy|pill)\.disableTooltip\b/g, `$1.${NEW}`);
        return applyRefs(code, refs);
    };

    head = fixCode(head);
    tail = fixCode(tail);
    return range ? head + tmpl + tail : head;
}

function walk(dir, acc = []) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, e.name);
        if (e.isDirectory()) walk(p, acc);
        else acc.push(p);
    }
    return acc;
}

let changed = 0;
for (const file of walk("src")) {
    const rel = file.split(path.sep).join("/");
    const ext = path.extname(file);
    if (![ ".ts", ".html" ].includes(ext)) continue;
    const src = fs.readFileSync(file, "utf8");
    if (!src.includes(OLD)) continue;
    let out;
    if (ext === ".html") {
        const r = transformTemplate(src);
        out = applyRefs(r.text, r.refs);
    } else {
        out = transformTs(src, rel);
    }
    if (out !== src) {
        fs.writeFileSync(file, out);
        changed++;
    }
}
console.log("files changed:", changed);

